Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(pub:Publisher|Organization),
      (a)-[:MENTIONS]->(sam:Person),
      (a)-[:MENTIONS]->(individual:Person)
WHERE (toLower(pub.name) CONTAINS 'fortune' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'fortune')
    OR toLower(pub.name) CONTAINS 'the verge' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'the verge')
    OR toLower(pub.name) CONTAINS 'techcrunch' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch'))
  AND (toLower(sam.name) CONTAINS 'sam bankman-fried' OR any(alias IN coalesce(sam.aliases, []) WHERE toLower(alias) CONTAINS 'sam bankman-fried'))
  AND individual <> sam
OPTIONAL MATCH (individual)-[:WORKS_FOR]->(org:Organization)
RETURN DISTINCT pub.name AS publisher, a.title AS article, a.published_on AS published_on, individual.name AS individual, org.name AS organization
