Cypher query: MATCH (a1:Article)-[:PUBLISHED_BY]->(pub1:Publisher),
      (a2:Article)-[:PUBLISHED_BY]->(pub2:Publisher),
      (a1)-[:MENTIONS]->(company:Organization),
      (a1)-[:MENTIONS]->(product:Product),
      (a2)-[:MENTIONS]->(company),
      (a2)-[:MENTIONS]->(product)
WHERE pub1 <> pub2
  AND (toLower(pub1.name) CONTAINS 'engadget' OR any(alias IN coalesce(pub1.aliases, []) WHERE toLower(alias) CONTAINS 'engadget'))
  AND (toLower(pub2.name) CONTAINS 'polygon' OR any(alias IN coalesce(pub2.aliases, []) WHERE toLower(alias) CONTAINS 'polygon'))
RETURN DISTINCT company.name AS company, product.name AS product
LIMIT 10
